package main

import "core:bytes"
import "core:net"
import "core:strconv"
import "core:strings"

MAX_HEADER_BYTES :: 16 * 1024
MAX_BODY_BYTES :: 1024 * 1024

HEADER_END :: "\r\n\r\n"

Request :: struct {
	method: string,
	path:   string,
	body:   []byte,
}

Response :: struct {
	status:       Status,
	content_type: string,
	body:         []byte,
}

Status :: enum {
	OK,
	Created,
	No_Content,
	Bad_Request,
	Not_Found,
	Method_Not_Allowed,
	Payload_Too_Large,
	Header_Fields_Too_Large,
	Internal_Server_Error,
	Not_Implemented,
	HTTP_Version_Not_Supported,
}

STATUS_LINES := [Status]string {
	.OK                         = "200 OK",
	.Created                    = "201 Created",
	.No_Content                 = "204 No Content",
	.Bad_Request                = "400 Bad Request",
	.Not_Found                  = "404 Not Found",
	.Method_Not_Allowed         = "405 Method Not Allowed",
	.Payload_Too_Large          = "413 Content Too Large",
	.Header_Fields_Too_Large    = "431 Request Header Fields Too Large",
	.Internal_Server_Error      = "500 Internal Server Error",
	.Not_Implemented            = "501 Not Implemented",
	.HTTP_Version_Not_Supported = "505 HTTP Version Not Supported",
}

// Read_Error is either a transport failure (no response is possible) or a
// protocol error that should be answered with the given status.
Read_Error :: union {
	Status,
	net.TCP_Recv_Error,
	net.TCP_Send_Error,
}

// read_request reads one HTTP/1.x request from `sock`. All returned memory
// (strings and body) is allocated with `allocator`.
read_request :: proc(sock: net.TCP_Socket, allocator := context.allocator) -> (req: Request, err: Read_Error) {
	buf := make([dynamic]byte, 0, 4096, allocator)
	header_end := -1
	for header_end < 0 {
		if len(buf) >= MAX_HEADER_BYTES {
			return {}, Status.Header_Fields_Too_Large
		}
		scan_from := max(len(buf) - (len(HEADER_END) - 1), 0)
		n := recv_append(sock, &buf, MAX_HEADER_BYTES - len(buf)) or_return
		if n == 0 {
			return {}, net.TCP_Recv_Error.Connection_Closed
		}
		if i := bytes.index(buf[scan_from:], transmute([]byte)string(HEADER_END)); i >= 0 {
			header_end = scan_from + i
		}
	}

	head := string(buf[:header_end])
	leftover := buf[header_end + len(HEADER_END):]

	request_line, _, header_lines := cut(head, "\r\n")
	method, _, rest := cut(request_line, " ")
	target, _, version := cut(rest, " ")
	if method == "" || target == "" || !strings.has_prefix(version, "HTTP/") {
		return {}, Status.Bad_Request
	}
	if !strings.has_prefix(version, "HTTP/1.") {
		return {}, Status.HTTP_Version_Not_Supported
	}
	req.method = method
	req.path = target

	content_length := 0
	has_length := false
	expect_continue := false
	for line in strings.split_lines_iterator(&header_lines) {
		name, found, value := cut(line, ":")
		if !found || name == "" {
			return {}, Status.Bad_Request
		}
		value = strings.trim_space(value)
		switch {
		case strings.equal_fold(name, "content-length"):
			n, ok := strconv.parse_int(value, 10)
			if !ok || n < 0 || (has_length && n != content_length) {
				return {}, Status.Bad_Request
			}
			content_length, has_length = n, true
		case strings.equal_fold(name, "transfer-encoding"):
			return {}, Status.Not_Implemented
		case strings.equal_fold(name, "expect"):
			expect_continue = strings.equal_fold(value, "100-continue")
		}
	}

	if content_length > MAX_BODY_BYTES {
		return {}, Status.Payload_Too_Large
	}
	if len(leftover) > content_length {
		// Pipelined requests are not supported; this connection serves one request.
		return {}, Status.Bad_Request
	}

	body := make([]byte, content_length, allocator)
	have := copy(body, leftover)
	if have < content_length && expect_continue {
		net.send_tcp(sock, transmute([]byte)string("HTTP/1.1 100 Continue\r\n\r\n")) or_return
	}
	for have < content_length {
		n := net.recv_tcp(sock, body[have:]) or_return
		if n == 0 {
			return {}, net.TCP_Recv_Error.Connection_Closed
		}
		have += n
	}
	req.body = body
	return req, nil
}

// write_response sends the status line, headers and body. The connection is
// always closed after one response, which is advertised to the client.
write_response :: proc(sock: net.TCP_Socket, res: Response) -> net.Network_Error {
	b := strings.builder_make(0, 256, context.temp_allocator)
	strings.write_string(&b, "HTTP/1.1 ")
	strings.write_string(&b, STATUS_LINES[res.status])
	strings.write_string(&b, "\r\nContent-Length: ")
	strings.write_int(&b, len(res.body))
	if res.content_type != "" {
		strings.write_string(&b, "\r\nContent-Type: ")
		strings.write_string(&b, res.content_type)
	}
	strings.write_string(&b, "\r\nConnection: close\r\n\r\n")

	net.send_tcp(sock, b.buf[:]) or_return
	if len(res.body) > 0 {
		net.send_tcp(sock, res.body) or_return
	}
	return nil
}

// recv_append receives up to `limit` bytes and appends them to `buf`.
@(private = "file")
recv_append :: proc(sock: net.TCP_Socket, buf: ^[dynamic]byte, limit: int) -> (n: int, err: net.TCP_Recv_Error) {
	old_len := len(buf)
	resize(buf, old_len + min(limit, max(cap(buf) - old_len, 4096)))
	n, err = net.recv_tcp(sock, buf[old_len:])
	resize(buf, old_len + max(n, 0))
	return
}

@(private = "file")
cut :: proc(s, sep: string) -> (before: string, found: bool, after: string) {
	i := strings.index(s, sep)
	if i < 0 {
		return s, false, ""
	}
	return s[:i], true, s[i + len(sep):]
}

package main

import "base:runtime"
import "core:fmt"
import "core:mem/virtual"
import "core:net"
import "core:os"
import "core:strconv"
import "core:sys/posix"
import "core:thread"
import "core:time"

// Idle clients are dropped after this long so they cannot pin a thread forever.
SOCKET_TIMEOUT :: 30 * time.Second

Connection :: struct {
	sock:  net.TCP_Socket,
	store: ^Store,
}

main :: proc() {
	if len(os.args) != 2 {
		fmt.eprintfln("usage: %s <port>", os.args[0])
		os.exit(2)
	}
	port, ok := strconv.parse_int(os.args[1], 10)
	if !ok || port < 1 || port > 65535 {
		fmt.eprintfln("invalid port: %q", os.args[1])
		os.exit(2)
	}

	// Writes to a peer that already hung up must fail with EPIPE, not kill the process.
	posix.signal(.SIGPIPE, auto_cast posix.SIG_IGN)

	store: Store
	store_init(&store, runtime.heap_allocator())
	defer store_destroy(&store)

	listener, err := net.listen_tcp({address = net.IP4_Loopback, port = port}, backlog = 1024)
	if err != nil {
		fmt.eprintfln("listen on 127.0.0.1:%d: %v", port, err)
		os.exit(1)
	}
	defer net.close(listener)

	for {
		client, _, accept_err := net.accept_tcp(listener)
		if accept_err != nil {
			fmt.eprintfln("accept: %v", accept_err)
			continue
		}
		conn := Connection{sock = client, store = &store}
		if thread.create_and_start_with_poly_data(conn, serve_connection, self_cleanup = true) == nil {
			fmt.eprintln("failed to start connection thread")
			net.close(client)
		}
	}
}

// serve_connection handles exactly one request and then closes the socket.
serve_connection :: proc(conn: Connection) {
	defer net.close(conn.sock)

	arena: virtual.Arena
	if virtual.arena_init_growing(&arena) != nil {
		return
	}
	defer virtual.arena_destroy(&arena)
	context.allocator = virtual.arena_allocator(&arena)
	context.temp_allocator = context.allocator

	_ = net.set_option(conn.sock, .Receive_Timeout, SOCKET_TIMEOUT)
	_ = net.set_option(conn.sock, .Send_Timeout, SOCKET_TIMEOUT)

	res: Response
	req, read_err := read_request(conn.sock)
	switch e in read_err {
	case nil:
		res = handle_request(conn.store, req)
	case Status:
		res = {status = e}
	case net.TCP_Recv_Error, net.TCP_Send_Error:
		return
	}

	if write_response(conn.sock, res) != nil {
		return
	}
	linger_close(conn.sock)
}

// linger_close half-closes the socket and drains any unread request bytes, so
// the kernel does not reset the connection and discard the response we just sent.
linger_close :: proc(sock: net.TCP_Socket) {
	_ = net.shutdown(sock, .Send)
	_ = net.set_option(sock, .Receive_Timeout, time.Second)
	drain: [4096]byte
	for _ in 0 ..< 512 {
		n, err := net.recv_tcp(sock, drain[:])
		if err != nil || n == 0 {
			return
		}
	}
}

package main

import "core:strings"

MAX_KEY_LEN :: 64

// handle_request maps a parsed request to a response. Response memory is
// allocated with `allocator`.
handle_request :: proc(store: ^Store, req: Request, allocator := context.allocator) -> Response {
	switch {
	case req.path == "/health":
		if req.method != "GET" {
			return {status = .Method_Not_Allowed}
		}
		return {status = .OK, content_type = "text/plain", body = transmute([]byte)string("ok")}

	case req.path == "/kv":
		if req.method != "GET" {
			return {status = .Method_Not_Allowed}
		}
		return {status = .OK, content_type = "application/json", body = keys_json(store, allocator)}

	case strings.has_prefix(req.path, "/kv/"):
		key := req.path[len("/kv/"):]
		if !is_valid_key(key) {
			return {status = .Bad_Request}
		}
		switch req.method {
		case "GET":
			value, found := store_get(store, key, allocator)
			if !found {
				return {status = .Not_Found}
			}
			return {status = .OK, content_type = "application/octet-stream", body = value}
		case "PUT":
			return {status = store_put(store, key, req.body) ? .Created : .OK}
		case "DELETE":
			return {status = store_delete(store, key) ? .No_Content : .Not_Found}
		case:
			return {status = .Method_Not_Allowed}
		}
	}
	return {status = .Not_Found}
}

// is_valid_key reports whether key matches [A-Za-z0-9_-]{1,64}.
is_valid_key :: proc(key: string) -> bool {
	if len(key) == 0 || len(key) > MAX_KEY_LEN {
		return false
	}
	for c in transmute([]byte)key {
		switch c {
		case 'A' ..= 'Z', 'a' ..= 'z', '0' ..= '9', '_', '-':
		case:
			return false
		}
	}
	return true
}

// keys_json renders every key as a sorted JSON array. Keys are restricted to
// characters that never need escaping.
keys_json :: proc(store: ^Store, allocator := context.allocator) -> []byte {
	keys := store_keys(store, allocator)
	defer {
		for k in keys {
			delete(k, allocator)
		}
		delete(keys, allocator)
	}

	size := 2
	for k in keys {
		size += len(k) + 3
	}
	b := strings.builder_make(0, size, allocator)
	strings.write_byte(&b, '[')
	for k, i in keys {
		if i > 0 {
			strings.write_byte(&b, ',')
		}
		strings.write_byte(&b, '"')
		strings.write_string(&b, k)
		strings.write_byte(&b, '"')
	}
	strings.write_byte(&b, ']')
	return b.buf[:]
}

package main

import "base:runtime"
import "core:slice"
import "core:strings"
import "core:sync"

// Store is a thread-safe in-memory key-value map. Keys and values are owned by the store.
Store :: struct {
	lock:      sync.RW_Mutex,
	entries:   map[string][]byte,
	allocator: runtime.Allocator,
}

store_init :: proc(s: ^Store, allocator := context.allocator) {
	s.allocator = allocator
	s.entries = make(map[string][]byte, allocator)
}

store_destroy :: proc(s: ^Store) {
	for k, v in s.entries {
		delete(k, s.allocator)
		delete(v, s.allocator)
	}
	delete(s.entries)
}

// store_put copies value into the store. Returns true if the key did not exist before.
store_put :: proc(s: ^Store, key: string, value: []byte) -> (created: bool) {
	owned := slice.clone(value, s.allocator)

	sync.rw_mutex_lock(&s.lock)
	defer sync.rw_mutex_unlock(&s.lock)

	if old, found := &s.entries[key]; found {
		delete(old^, s.allocator)
		old^ = owned
		return false
	}
	s.entries[strings.clone(key, s.allocator)] = owned
	return true
}

// store_get returns a copy of the stored value, allocated with `allocator`.
store_get :: proc(s: ^Store, key: string, allocator := context.allocator) -> (value: []byte, found: bool) {
	sync.rw_mutex_shared_lock(&s.lock)
	defer sync.rw_mutex_shared_unlock(&s.lock)

	stored := s.entries[key] or_return
	return slice.clone(stored, allocator), true
}

store_delete :: proc(s: ^Store, key: string) -> (deleted: bool) {
	sync.rw_mutex_lock(&s.lock)
	defer sync.rw_mutex_unlock(&s.lock)

	k, v := delete_key(&s.entries, key)
	if k == "" {
		return false
	}
	delete(k, s.allocator)
	delete(v, s.allocator)
	return true
}

// store_keys returns every key, sorted ascending by byte order. The strings are
// cloned with `allocator`, as is the slice.
store_keys :: proc(s: ^Store, allocator := context.allocator) -> []string {
	keys: [dynamic]string
	{
		sync.rw_mutex_shared_lock(&s.lock)
		defer sync.rw_mutex_shared_unlock(&s.lock)

		keys = make([dynamic]string, 0, len(s.entries), allocator)
		for k in s.entries {
			append(&keys, strings.clone(k, allocator))
		}
	}
	slice.sort(keys[:])
	return keys[:]
}
